def getPassword(prompt, confirmPassword=None):
    """
    Prompt for a password.

    @param prompt: The prompt to display.

    @param confirmPassword: If C{None}, the password is returned as is.
        Otherwise, the user is prompted to confirm the password.

    @return: The password.
    """
    password = getpass.getpass(prompt)
    if confirmPassword is None:
        return password
    while True:
        confirm = getpass.getpass('Confirm %s: ' % (prompt,))
        if confirm == password:
            return password
        print "Passwords do not match."


def get_password_from_config(config, section, option):
    """
    Get a password from a config file.

    @param config: The config file.

    @param section: The section in the config file.

    @param option: The option in the config file.

    @return: The password.
    """
    if config.has_option(section, option):
        return config.get(section, option)
    password = gtpswd('%s password: ' % (section,), confirmPassword=True)
    config.set(section, option, password)
    return password


def get_password_from_config_file(configFile):
    """
    Get a password from a config file.

    @param configFile: The config file.

    @return: The password.
    """
    config = ConfigParser.ConfigParser()
    config.read(configFile)
    return get_password_from_config(config, 'user', 'password')


